-- Datos de prueba para bd_tutorias (50 INSERT por cada una de las 7 tablas).
-- Se ejecuta SOBRE el esquema y los registros iniciales compartidos por el usuario.
-- No elimina, modifica ni recrea tablas ni vistas.
-- Los roles Estudiante, Tutor y Administrador deben existir previamente.
-- Los registros adicionales de roles son de demostracion; no se asignan a usuarios.
-- Contrasena de los 50 usuarios de prueba: Tutorias2026! (hash bcrypt compatible con password_verify de PHP).
-- Ejecutar una sola vez sobre una base de datos preparada.
USE bd_tutorias;
START TRANSACTION;

-- ROLES: 50 registros nuevos


-- CARRERAS: 50 registros nuevos


-- MATERIAS: 50 registros nuevos


-- USUARIOS: 50 registros nuevos


-- TUTORIAS: 50 registros nuevos


-- HORARIOS: 50 registros nuevos


-- SOLICITUDES: 50 registros nuevos


COMMIT;

-- Comprobacion de los registros de prueba:
-- Se insertan 50 filas adicionales por tabla; las filas previas se conservan.
SELECT 'roles' AS tabla, COUNT(*) AS total FROM roles UNION ALL
SELECT 'carreras', COUNT(*) FROM carreras UNION ALL
SELECT 'materias', COUNT(*) FROM materias UNION ALL
SELECT 'usuarios', COUNT(*) FROM usuarios UNION ALL
SELECT 'tutorias', COUNT(*) FROM tutorias UNION ALL
SELECT 'horarios', COUNT(*) FROM horarios UNION ALL
SELECT 'solicitudes', COUNT(*) FROM solicitudes;
